# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">TELLING THE TIME (WHAT TIME IS IT?)</text>\n  <rect x="20" y="45" width="320" height="195" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <circle cx="180" cy="142" r="72" fill="#ffffff" stroke="#1d4ed8" stroke-width="3"/>\n  <text x="180" y="62" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">o\'clock (Tam)</text>\n  <text x="180" y="232" text-anchor="middle" font-size="12" font-weight="bold" fill="#1d4ed8">half past (Buçuk)</text>\n  <text x="262" y="146" text-anchor="start" font-size="11" font-weight="bold" fill="#15803d">quarter past</text>\n  <text x="98" y="146" text-anchor="end" font-size="11" font-weight="bold" fill="#be123c">quarter to</text>\n  <text x="215" y="110" text-anchor="middle" font-size="11" font-weight="bold" fill="#16a34a">PAST (Geçiyor)</text>\n  <text x="145" y="110" text-anchor="middle" font-size="11" font-weight="bold" fill="#e11d48">TO (Var)</text>\n  <line x1="180" y1="70" x2="180" y2="214" stroke="#94a3b8" stroke-dasharray="4,4"/>\n\n  <rect x="360" y="45" width="320" height="195" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="520" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Examples (Saat Örnekleri)</text>\n  <text x="380" y="96" font-size="12" font-weight="bold" fill="#14532d">• 08:00 ➔ It is eight o\'clock.</text>\n  <text x="380" y="122" font-size="12" font-weight="bold" fill="#14532d">• 08:15 ➔ It is quarter past eight.</text>\n  <text x="380" y="148" font-size="12" font-weight="bold" fill="#14532d">• 08:30 ➔ It is half past eight.</text>\n  <text x="380" y="174" font-size="12" font-weight="bold" fill="#14532d">• 08:45 ➔ It is quarter to nine.</text>\n  <text x="380" y="200" font-size="12" font-weight="bold" fill="#14532d">• 09:20 ➔ It is twenty past nine.</text>\n  <text x="380" y="226" font-size="12" font-weight="bold" fill="#14532d">• 09:50 ➔ It is ten to ten.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">DAILY SCHOOL ROUTINES &amp; PRESENT SIMPLE TENSE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Asking About Time of Actions</text>\n  <text x="45" y="100" font-size="12" font-weight="bold" fill="#713f12">Q: What time do you wake up?</text>\n  <text x="45" y="120" font-size="12" fill="#334155">A: I wake up at seven o\'clock (07:00).</text>\n  <text x="45" y="152" font-size="12" font-weight="bold" fill="#713f12">Q: What time does the Maths class start?</text>\n  <text x="45" y="172" font-size="12" fill="#334155">A: It starts at half past eight (08:30).</text>\n  <text x="45" y="204" font-size="12" font-weight="bold" fill="#854d0e">Prepositions: AT + time | ON + days | IN + morning</text>\n  <text x="45" y="224" font-size="11" fill="#475569">at 9:00 / at noon  |  on Monday  |  in the afternoon</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Timetable &amp; Numbers (50 - 100)</text>\n  <text x="380" y="100" font-size="12" font-weight="bold" fill="#6b21a8">• a weekday (Hafta içi) / weekend (Hafta sonu)</text>\n  <text x="380" y="124" font-size="12" font-weight="bold" fill="#6b21a8">• double lessons (Blok/Çift ders)</text>\n  <text x="380" y="148" font-size="12" font-weight="bold" fill="#6b21a8">• have a break (Teneffüs yapmak) / lunch (Öğle yemeği)</text>\n  <text x="380" y="176" font-size="12" font-weight="bold" fill="#7e22ce">Numbers 50 - 100:</text>\n  <text x="380" y="198" font-size="11" fill="#334155">50: fifty | 60: sixty | 70: seventy | 80: eighty</text>\n  <text x="380" y="218" font-size="11" fill="#334155">90: ninety | 100: one hundred (There are 60 minutes)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">OBJECT PRONOUNS &amp; SOCIAL CLASSROOM LANGUAGE</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Subject ➔ Object Pronouns</text>\n  <text x="182" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">I ➔ me  |  You ➔ you  |  We ➔ us</text>\n  <text x="182" y="124" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">He ➔ him  |  She ➔ her  |  It ➔ it</text>\n  <text x="182" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#155e75">They ➔ them</text>\n  <text x="182" y="182" text-anchor="middle" font-size="11" fill="#0f172a">"Can you give me your dictionary?"</text>\n  <text x="182" y="204" text-anchor="middle" font-size="11" fill="#0f172a">"Mr. Yılmaz teaches us English."</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">Target Social Expressions</text>\n  <text x="380" y="102" font-size="12" font-weight="bold" fill="#9f1239">• Give me a hand! (Bana yardım et!)</text>\n  <text x="380" y="130" font-size="12" font-weight="bold" fill="#9f1239">• Don\'t skip the lesson! (Dersi kaçırma/asma!)</text>\n  <text x="380" y="158" font-size="12" font-weight="bold" fill="#9f1239">• Make the grade! (Başarılı ol / Sınıfı geç!)</text>\n  <text x="380" y="186" font-size="12" font-weight="bold" fill="#9f1239">• I don\'t feel all right. (İyi hissetmiyorum.)</text>\n  <text x="380" y="214" font-size="12" font-weight="bold" fill="#9f1239">• I\'d love to. (Çok isterim / Memnuniyetle.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
